    for i in range(1, n):
        x = a + i * h
        total += 2 * f(x) if i % 2 == 0 else 4 * f(x)
    # Simpson's rule requires n even
    if n % 2 == 0:
        return total * h / 3
    else:
        # fall back to trapezoidal
        s = (f(a) + f(b)) / 2
        for i in range(1, n):
            s += f(a + i*h)
        return s * h

