def solve(n, min_group_size, max_group_size, output):
    count = 0
    # iterate over possible numbers of each group size from min to max
    # general: find non-negative integer solutions summing group sizes to n
    # using two sizes min and max
    solutions = []
    for a in range(n // min_group_size + 1):
        rem = n - a * min_group_size
        if rem < 0:
            break
        if max_group_size != min_group_size:
            if rem % max_group_size == 0:
                b = rem // max_group_size
                solutions.append((a, b))
        else:
            if rem == 0:
                solutions.append((a, 0))
    return len(solutions)

